const INFER_RULES: ReadonlyArray<[RegExp, OsId]> = [
  [/\braspbian\b|\braspberry\b|\braspi\b/i, "raspbian"],
  [/\bubuntu\b/i, "ubuntu"],
  [/\bdebian\b/i, "debian"],
  [/\balmalinux\b|\balma\b/i, "alma"],
  [/\brocky\b/i, "rocky"],
  [/\bcentos\b/i, "centos"],
  [/\bfedora\b/i, "fedora"],
  [/\bredhat\b|\brhel\b|\bred\s*hat\b/i, "redhat"],
  [/\balpine\b/i, "alpine"],
  [/\bamazon\b|\bamzn\b/i, "amazon"],
  [/\barch\b|\bmanjaro\b/i, "arch"],
  [/\bsuse\b|\bopensuse\b|\bsles\b/i, "suse"],
  [/\bgentoo\b/i, "gentoo"],
  [/\bmageia\b/i, "mageia"],
  [/\bfreebsd\b/i, "freebsd"],
  [/\bopenbsd\b/i, "openbsd"],
  [/\bnetbsd\b/i, "netbsd"],
  [/\bmacos\b|\bdarwin\b/i, "macos"],
  [/\bmikrotik\b|\brouteros\b/i, "routeros"],
  [/\bcisco\b/i, "cisco"],
  [/\bwindows\b|\bwin32\b|\bwin64\b/i, "windows"]
]

export function resolveHostOs(host: Pick<Host, "os" | "label" | "hostname" | "username" | "group" | "tags">): OsId | null {
  if (host.os && OS_BY_ID[host.os]) return host.os
  const haystack = [host.label, host.hostname, host.username, host.group, ...(host.tags ?? [])].join(" ")
  for (const [re, os] of INFER_RULES) {
    if (re.test(haystack)) return os
  }
  return null
}

export function OsGlyph({ kind, size = 20 }: { kind: OsId | "host" | "group"; size?: number }) {
  const def = SVGS[kind] ?? SVGS.host
  return (
    <svg width={size} height={size} viewBox={def.viewBox} fill="none" aria-hidden>
      {def.paths.map((p, i) => (
        <path
          key={i}
          d={p.d}
          fill="currentColor"
          fillRule={p.evenOdd ? "evenodd" : undefined}
          clipRule={p.evenOdd ? "evenodd" : undefined}
          fillOpacity={p.opacity ? Number(p.opacity) : undefined}
        />
      ))}
    </svg>
  )
}

export function HostBadge({ host }: { host: Pick<Host, "os" | "protocol" | "label" | "hostname" | "username" | "group" | "tags"> }) {
  const os = resolveHostOs(host)
  const info = os ? OS_BY_ID[os] : undefined
  const bg = info?.color ?? DEFAULT_BADGE_COLOR
  return (
    <div className="card-icon os-badge" style={{ backgroundColor: bg }} title={info?.label ?? host.protocol.toUpperCase()}>
      {os ? <OsGlyph kind={os} size={20} /> : host.protocol === "ssh" ? <OsGlyph kind="host" size={20} /> : host.protocol[0].toUpperCase()}
    </div>
  )
}

export function GroupBadge() {
  return (
    <div className="card-icon os-badge" style={{ backgroundColor: DEFAULT_BADGE_COLOR }}>
      <OsGlyph kind="group" size={20} />
    </div>
  )
}
